// mcpWriteFile atomically writes through a private temporary file, creating
// parent directories and preserving existing nonzero permissions.
func mcpWriteFile(path, content string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return err
	}
	mode := os.FileMode(0600)
	if info, err := os.Stat(path); err == nil {
		if perm := info.Mode().Perm(); perm != 0 {
			mode = perm
		}
	}
	tmp := path + ".tmp-" + strconv.FormatInt(time.Now().UnixNano(), 10)
	if err := os.WriteFile(tmp, []byte(content), mode); err != nil {
		return err
	}
	return replaceFile(tmp, path)
}

// mcpEnvRef matches the ${VAR} references an entry's header values carry.
var mcpEnvRef = regexp.MustCompile(`\$\{([A-Za-z_][A-Za-z0-9_]*)\}`)

// mcpCodexBearerEnv reports the variable of an `Authorization: Bearer ${VAR}`
// header, the one value Codex's bearer_token_env_var expresses.
func mcpCodexBearerEnv(header, value string) (string, bool) {
	match := mcpEnvRef.FindStringSubmatch(value)
	if !strings.EqualFold(header, "Authorization") || match == nil || value != "Bearer "+match[0] {
		return "", false
	}
	return match[1], true
}

// mcpEntryForClient rewrites ${VAR} header references into the client's own
// syntax. A client that expands nothing gets no such header rather than a
// literal one it would send as-is.
func mcpEntryForClient(clientID string, entry mcpEntry) (mcpEntry, string) {
	style := map[string]string{"cursor": "env-colon", "vscode": "env-colon", "windsurf": "env-colon", "opencode": "brace-env", "codex": "codex", "gemini-cli": "none", "zed": "none"}[clientID]
	if style == "" || len(entry.Headers) == 0 {
		return entry, ""
	}
	headers := map[string]string{}
	dropped := []string{}
	for header, value := range entry.Headers {
		switch {
		case !mcpEnvRef.MatchString(value):
			headers[header] = value
		case style == "env-colon":
			headers[header] = mcpEnvRef.ReplaceAllString(value, "$${env:${1}}")
		case style == "brace-env":
			headers[header] = mcpEnvRef.ReplaceAllString(value, "{env:${1}}")
		case style == "codex":
			// Codex reads a whole header value from one variable, or a bearer
			// token from one; a prefix other than Bearer has no spelling.
			if _, ok := mcpCodexBearerEnv(header, value); ok || mcpEnvRef.FindString(value) == value {
				headers[header] = value
			} else {
				dropped = append(dropped, header)
			}
		default:
			dropped = append(dropped, header)
		}
	}
	sort.Strings(dropped)
	if len(headers) == 0 {
		headers = nil
	}
	entry.Headers = headers
	if len(dropped) == 0 {
		return entry, ""
	}
	if style == "codex" {
		return entry, "codex reads a header from an environment variable only as its whole value or a bearer token, so the entry omits " + strings.Join(dropped, ", ") + "; the client signs in with MCP authorization when the server supports it."
	}
	return entry, clientID + " does not expand environment variables in headers, so the entry omits " + strings.Join(dropped, ", ") + "; the client signs in with MCP authorization when the server supports it."
}

